  (options.client ?? client).get<
    GetVerifyLiabilitiesByProofIdInclusionResponses,
    GetVerifyLiabilitiesByProofIdInclusionErrors,
    ThrowOnError
  >({ url: '/verify/liabilities/{proofId}/inclusion', ...options });

/**
 * Get ZKP verification key
 *
 * Returns the global Groth16 circuit verification key for independent proof
 */
export const getVerifyZkpVk = <ThrowOnError extends boolean = false>(
  options?: Options<GetVerifyZkpVkData, ThrowOnError>
) =>
  (options?.client ?? client).get<GetVerifyZkpVkResponses, GetVerifyZkpVkErrors, ThrowOnError>({
    url: '/verify/zkp/vk',
    ...options,
  });
